  $$("[data-irt]").forEach(b => (b.onclick = () => { IR.tab = b.dataset.irt; IR.pedit = false; IR.padd = false; IR.pj = null; IR.e = null; IR.k = null; re(); }));
  $$("[data-iropen]").forEach(b => (b.onclick = () => { IR.plan = b.dataset.iropen; IR.tab = "plan"; re(); }));
  const sel = $("#ir-sel"); if (sel) sel.onchange = () => { IR.plan = sel.value; IR.pedit = false; IR.pj = null; IR.e = null; re(); };
  // plans
  const np = $("#ir-newplan"); if (np) np.onclick = () => { IR.tab = "plan"; IR.padd = true; IR.pn = null; re(); };
  const pn = IR.pn;
  if (pn) { const sy = (s, k, ev, f) => { const e = $(s); if (e) e[ev || "oninput"] = () => { pn[k] = f ? f(e) : e.value; if (ev === "onchange") re(); }; }; sy("#ir-n-prog", "prog", "onchange"); sy("#ir-n-pull", "pull", "onchange", e => e.checked); sy("#ir-n-role", "role", "onchange"); sy("#ir-n-host", "host"); sy("#ir-n-due", "due"); }
  const ns = $("#ir-nsave"); if (ns) ns.onclick = () => { const r = irPlanAdd({ prog: pn.prog, pull: pn.pull, role: pn.role, host: pn.host, due: pn.due }); if (!r.startsWith("IP-")) { toast(r); return; } commit(); IR.plan = r; IR.padd = false; IR.pn = null; re(); toast(L("สร้างแผนแล้ว", "Plan added")); };
  const nc = $("#ir-ncancel"); if (nc) nc.onclick = () => { IR.padd = false; IR.pn = null; re(); };
  const pe = $("#ir-pedit"); if (pe) pe.onclick = () => { IR.pedit = true; re(); };
  const pc = $("#ir-pcancel"); if (pc) pc.onclick = () => { IR.pedit = false; re(); };
  const ga = $("#ir-agadd"); if (ga) ga.onclick = () => { const t = document.createElement("div"); t.innerHTML = irAgRow({ name: "", role: "support" }); const r = t.firstElementChild; $("#ir-ags").appendChild(r); r.querySelector("[data-iragx]").onclick = () => r.remove(); };
  $$("[data-iragx]").forEach(b => (b.onclick = () => b.closest("[data-irag]").remove()));
  const ps = $("#ir-psave"); if (ps) ps.onclick = () => { const v = { ns: val("#ir-f-ns"), policy: val("#ir-f-policy"), obs: val("#ir-f-obs"), due: val("#ir-f-due"), agencies: $$("[data-irag]").map(r => ({ name: r.querySelector('[data-k="ag-name"]').value, role: r.querySelector('[data-k="ag-role"]').value, mine: !!r.dataset.mine })) }; if (say(irPlanSave(irCur().id, v))) return; commit(); IR.pedit = false; re(); toast(L("บันทึกแผนแล้ว", "Plan saved")); };
  // outcomes, goals, approaches
  const kind = IR.tab, hold = el => el.dataset.irH;
  const ea = $("[data-ir-ea]"); if (ea) ea.onclick = () => { IR.e = { kind, id: null, name: "", term: "" }; re(); };
  $$("[data-ir-ee]").forEach(b => (b.onclick = () => { const h = (irCur()[IR_KIND[kind].key] || []).find(x => x.id === b.dataset.irEe); IR.e = { kind, id: h.id, name: h.name, term: h.term || "" }; re(); }));
  $$("[data-ir-ed]").forEach(b => (b.onclick = () => { if (say(irEntryDel(irCur().id, kind, b.dataset.irEd))) return; commit(); re(); toast(L("ลบแล้ว", "Deleted")); }));
  const em = $("#ir-emodal"); if (em) { const close = () => { IR.e = null; re(); }; $("#ir-ex").onclick = close; $("#ir-ecancel").onclick = close; em.onclick = e => { if (e.target === em) close(); }; em.onkeydown = e => { if (e.key === "Escape") close(); };
    $("#ir-e-name").oninput = e => (IR.e.name = e.target.value); const t = $("#ir-e-term"); if (t) t.onchange = e => (IR.e.term = e.target.value);
    $("#ir-esave").onclick = () => { if (say(irEntrySave(irCur().id, IR.e.kind, { name: IR.e.name, term: IR.e.term }, IR.e.id))) return; commit(); IR.e = null; re(); toast(L("บันทึกแล้ว", "Saved")); }; }
  // KPIs of the entries
  const kOf = (h, kid) => ((irHolder(irCur(), kind, h) || {}).kpis || []).find(x => x.id === kid);
  const lab = h => `${tx(IR_KIND[kind].one)} : ${(irHolder(irCur(), kind, h) || {}).name || ""}`;
  $$("[data-ir-ka]").forEach(b => (b.onclick = () => { const h = hold(b); irKOpen(lab(h), null, k => irKpiSave(irCur().id, kind, h, k, null)); }));
  $$("[data-ir-ke]").forEach(b => (b.onclick = () => { const h = hold(b), kid = b.dataset.irK; irKOpen(lab(h), kOf(h, kid), k => irKpiSave(irCur().id, kind, h, k, kid)); }));
  $$("[data-ir-kd]").forEach(b => (b.onclick = () => { if (say(irKpiDel(irCur().id, kind, hold(b), b.dataset.irK))) return; commit(); re(); toast(L("ลบตัวชี้วัดแล้ว", "KPI deleted")); }));
  // projects
