    [["#ir-j-agency", "agency"], ["#ir-j-name", "name"], ["#ir-j-grp", "group"], ["#ir-j-area", "area"], ["#ir-j-bud", "budget"], ["#ir-j-note", "note"]].forEach(([s, k]) => { const e = $(s); if (e) e.oninput = () => (v[k] = e.value); });
